# Replace whole text nodes/attributes first to prevent short phrases from altering longer sentences.
import re
for p in list(Path('.').glob('*.html')):
 if p.stem.endswith('-en'): continue
 s=p.read_text(encoding='utf-8')
 def translate_text(match):
  text=match.group(1)
  return '>'+ (mapping[text] if text in mapping else text.replace(text.strip(), mapping.get(text.strip(), text.strip())) if text.strip() else text) +'<'
 s=re.sub(r'>([^<>]+)<',translate_text,s)
 for attr in ('content','aria-label','title','placeholder'):
  s=re.sub(r'('+attr+r'=")([^"]*)(")',lambda m:m[1]+mapping.get(m[2],m[2])+m[3],s)
 s=s.replace('lang="es"','lang="en"').replace('Read this page in English','Leer esta página en español').replace('lang="en" hreflang="en"','lang="es" hreflang="es"').replace('>EN</a>','>ES</a>')
 # Titles include the site owner's name.
 for source,target in mapping.items():
  s=s.replace('<title>'+source+' |','<title>'+target+' |')
 for name in ('index','publicaciones','libros','servicios','conversaciones','videos','charlas','perfil'):
  s=s.replace('href="'+name+'.html','href="'+name+'-en.html')
 s=s.replace('href="'+p.stem+'-en.html" lang="es"','href="'+p.name+'" lang="es"')
 s=s.replace('<span>IA</span>','<span>AI</span>')
 Path(p.stem+'-en.html').write_text(s,encoding='utf-8')
print('Created English versions of all Spanish pages')
